<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_admin();require_once __DIR__.'/../includes/db.php';
$skills=$conn->query("SELECT s.skill_id,s.user_id,s.title,s.description,s.level,s.status,s.category_name,u.F_name,u.L_name,COUNT(sb.booking_id) AS booking_count FROM `SKILL` s JOIN `USER` u ON u.user_id=s.user_id LEFT JOIN `SESSION_BOOKING` sb ON sb.skill_id=s.skill_id GROUP BY s.skill_id,s.user_id,s.title,s.description,s.level,s.status,s.category_name,u.F_name,u.L_name ORDER BY s.skill_id DESC")->fetch_all(MYSQLI_ASSOC);
$pageTitle='Manage skills';require __DIR__.'/../includes/header.php';
?>
<section class="py-4 py-lg-5"><div class="container"><div class="mb-4"><div class="eyebrow text-primary mb-1">Catalog moderation</div><h1 class="section-title h2">Skills</h1></div><div class="surface-card overflow-hidden"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Skill</th><th>Owner</th><th>Category / level</th><th>Bookings</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($skills as $skill):?><tr><td><strong><?=e($skill['title'])?></strong><div class="small text-secondary"><?=e(mb_strimwidth((string)$skill['description'],0,75,'...'))?></div></td><td><?=e(trim($skill['F_name'].' '.$skill['L_name']))?></td><td><?=e($skill['category_name']?:'General')?> / <?=e($skill['level']?:'Any')?></td><td><?=(int)$skill['booking_count']?></td><td><span class="badge text-bg-<?=e(status_class($skill['status']))?>"><?=e($skill['status'])?></span></td><td class="text-end"><form method="post" action="<?=e(url('actions/admin_skill_status.php'))?>"><?=csrf_field()?><input type="hidden" name="skill_id" value="<?=(int)$skill['skill_id']?>"><input type="hidden" name="status" value="<?=$skill['status']==='active'?'inactive':'active'?>"><button class="btn btn-sm btn-outline-<?=$skill['status']==='active'?'danger':'success'?>"><?=$skill['status']==='active'?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></section>
